// Static hub pages generated by scripts/pages.js into public/_pages. Shared by
// the Worker and the Vite dev server (vite.config.ts).
import { categorySlugs } from '../src/utils/groupPaths'

// Marker every generated hub page carries; a missing file falls back to the
// SPA's index.html, which doesn't.
export const HUB_MARKER = '<meta name="atlas-page" content="hub" />'

// Path segments -> generated file under public/_pages (extension-less, so the
// assets binding resolves it to the .html / index.html).
export function hubAsset(segments: string[]): string | null {
  const [first, second] = segments
  if (first === 'theories' && segments.length === 1) return '/_pages/theories'
  if (first === 'mentions' && segments.length === 1) return '/_pages/mentions'
  if (first === 'quiz' && segments.length === 1) return '/_pages/quiz'
  if (first === 'theories' && segments.length === 2 && categorySlugs.has(second)) return `/_pages/category/${second}`
  if ((first === 'questions' || first === 'compare') && segments.length <= 2) {
    return second ? `/_pages/${first}/${second}` : `/_pages/${first}/`
  }
  return null
}
